class Solution {
  public int mySqrt(int x) {
    int r = (int) Math.sqrt(x);
    while ((long) (r + 1) * (r + 1) <= x) {
      r++;
    }
    while ((long) r * r > x) {
      r--;
    }
    return r;
  }
}

class Solution:
    def mySqrt(self, x: int) -> int:
        r = int(x ** 0.5)
        while (r + 1) * (r + 1) <= x:
            r += 1
        while r * r > x:
            r -= 1
        return r

impl Solution {
  pub fn my_sqrt(x: i32) -> i32 {
    let mut r = (x as f64).sqrt() as i64;
    while (r + 1) * (r + 1) <= x as i64 {
      r += 1;
    }
    while r * r > x as i64 {
      r -= 1;
    }
    r as i32
  }
}

const mySqrt = (x: number): number => {
  let r = Math.floor(Math.sqrt(x));
  while ((r + 1) * (r + 1) <= x) r++;
  while (r * r > x) r--;
  return r;
};
